from pyramid.decorator import reify
from pyramid.url import route_url, resource_url, static_url, current_route_url

class URLGenerator(object):
    def __init__(self, context, request):
        self.context = context
        self.request = request

    @property
    def context(self):
        return resource_url(self.context, self.request)

    @property
    def app(self):
        return self.request.application_url

    def route(self, route_name, *elements, **kw):
        return route_url(route_name, self.request, *elements, **kw)

    # sugar for calling url('home')
    __call__ = route

    def current(self, *elements, **kw):
        return current_route_url(self.request, *elements, **kw)

    #@reify
    def static(self):
        return static_url('baseline:static/', self.request)

    #@reify
    def deform(self):
        return static_url('deform:static/', self.request)

