from django.conf import settings
from django.contrib.auth.models import User
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# If we get here, either we didn't find a matching user, or the password was wrong.
		# Before concluding that we should return None, let's check the vanilla User model to
		# see if maybe we should be creating a new custom User for this auth attempt.
		try:
			user = User.objects.get(username=username)
			if user.check_password(password):
				custom_user = self.user_class()
				custom_user.username = user.username
				custom_user.email = user.email
				custom_user.first_name = user.first_name
				custom_user.last_name = user.last_name
				custom_user.is_staff = user.is_staff
				custom_user.is_active = user.is_active
				custom_user.set_password(user.password)  # Ensure password hash is appropriate for new custom User model
				custom_user.save()
				user.delete()
				return custom_user
		except User.DoesNotExist:
			pass

		# If we get here, we weren't able to authenticate this user via the vanilla User model,
		# either because a) there was no matching user, or b) the password was wrong. Either way,
		# we should just return None now to allow other backends the chance to authenticate this
		# attempt (if any other backends are defined, and are willing to take on this authentication).
		return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

