from django.conf import settings
from django.contrib.auth.models import User
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model


class UserModelBackend(ModelBackend):
    def authenticate(self, username=None, password=None):
        try:
            user = self.user_class.objects.get(username=username)
            if user.check_password(password):
                return user
        except self.user_class.DoesNotExist:
            pass

        # if we get here, we need to see if there's a default django user
        # that matches our criteria. If so, we need to create a new custom
        # user and clone all information across, effectively overriding the
        # default django user with our own custom one
        try:
            user = User.objects.get(username=username)
            if user.check_password(password):
                admin_data = {
                    'date_joined': user.date_joined,
                    'email': user.email,
                    'is_active': user.is_active,
                    'is_staff': user.is_staff,
                    'is_superuser': user.is_superuser,
                    'last_login': user.last_login,
                    'username': user.username,
                }
                for field in admin_data.keys():
                    getattr(user, field)
                # create our new user, and assign the admin_data to it.
                new_user = self.user_class(**admin_data)
                new_user.save()
                # since we're using the default Django authenticate() call,
                # and hence the get_or_create() call in place, we need to
                # explicitly delete the vanilla django User, and return our
                # new custom User instance
                user.delete()
                return new_user
        except User.DoesNotExist:
            return None

    def get_user(self, user_id):
        try:
            return self.user_class.objects.get(pk=user_id)
        except self.user_class.DoesNotExist:
            return None

    @property
    def user_class(self):
        if not hasattr(self, '_user_class'):
            self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
            if not self._user_class:
                raise ImproperlyConfigured('Could not get custom user model')
        return self._user_class

