from django.conf import settings
from django.contrib.auth.models import User
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# Since we're using a custom User model, rare is the day we'll get here.
		# If we do, it's almost certainly because create_superuser() just created
		# a vanilla Django User because the app it was trying to create was not
		# yet loaded at the time the create_superuser() command was run.

		# Therefore, we first check if a user with the same username exists in
		# the vanilla Users table, and if so, we clone all its information to
		# a new custom User instance, at which stage we delete the vanilla User
		# and return the new custom User instance.

		try:
			u = User.objects.get(username=username)
		except User.DoesNotExist:
			return None

		if u.check_password(password):
			du = self.user_class(
				username = u.username,
				email = u.email,
				first_name = u.first_name,
				last_name = u.last_name,
				is_active = u.is_active,
				is_staff = u.is_staff,
				is_superuser = u.is_superuser,
				date_joined = u.date_joined,
			)
			du.set_password(u.password)
			du._state.adding = True
			du.save()
			u.delete()
			u = du

			return u

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

